def lee_ready_classify(trade_price, midpoint, prev_trade_price, prev_classification):
    if trade_price > midpoint:
        return "Buy"
    elif trade_price < midpoint:
        return "Sell"
    else:
        # At the midpoint: fall back to the tick rule
        if trade_price > prev_trade_price:
            return "Buy"
        elif trade_price < prev_trade_price:
            return "Sell"
        else:
            return prev_classification  # zero tick: carry forward

# Reproducing the worked table above
trades = [
    (500.05, 500.025),
    (500.00, 500.025),
    (500.025, 500.025),
    (499.95, 499.975),
    (499.975, 499.975),
]

classifications = []
prev_price, prev_class = None, None
for price, mid in trades:
    c = lee_ready_classify(price, mid, prev_price, prev_class)
    classifications.append(c)
    prev_price, prev_class = price, c

print(classifications)
# ['Buy', 'Sell', 'Buy', 'Sell', 'Buy']
